const PLUGIN_ID = "profile-music-player";

const ICONS = {
  music: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 3v10.55c-.59-.34-1.27-.55-2-.55-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"/></svg>`,
  play: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>`,
  pause: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>`,
  prev: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 6h2v12H6zm3.5 6 8.5 6V6z"/></svg>`,
  next: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 18l8.5-6L6 6v12zm2-6v0zm10 0V6h2v12h-2z"/></svg>`,
  close: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M19 6.41 17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>`,
  minimize: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M19 13H5v-2h14v2z"/></svg>`,
};

function formatTime(sec) {
  if (!Number.isFinite(sec) || sec < 0) return "0:00";
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${s.toString().padStart(2, "0")}`;
}

function getAudioMeta(doc) {
  let title = doc.file_name || `Трек ${doc.id}`;
  let artist = "";
  let duration = doc.duration || 0;

  for (const attr of doc.attributes || []) {
    if (attr._ === "documentAttributeAudio") {
      if (attr.title) title = attr.title;
      if (attr.performer) artist = attr.performer;
      if (attr.duration) duration = attr.duration;
    }
    if (attr._ === "documentAttributeFilename" && !attr.title) {
      title = attr.file_name?.replace(/\.[^.]+$/, "") || title;
    }
  }

  return { title, artist, duration };
}

export const meta = {
  id: PLUGIN_ID,
  name: "Profile Music Player",
  version: "1.0.0",
  description: "Плеер для музыки из профиля",
};

export function setup(api) {
  let tracks = [];
  let currentIndex = api.storage.getForPlugin(PLUGIN_ID, "trackIndex") || 0;
  let volume = api.storage.getForPlugin(PLUGIN_ID, "volume") ?? 1;
  let visible = api.storage.getForPlugin(PLUGIN_ID, "visible") ?? false;
  let minimized = false;
  let isDragging = false;
  let dragOffset = { x: 0, y: 0 };

  const audio = new Audio();
  audio.volume = volume;

  let root = null;
  let fab = null;
  let els = {};

  function $(sel) {
    return root?.querySelector(sel);
  }

  function createPlayer() {
    fab = document.createElement("button");
    fab.className = "pmp-fab";
    fab.innerHTML = ICONS.music;
    fab.title = "Музыка профиля";
    fab.addEventListener("click", () => togglePlayer(true));
    document.body.appendChild(fab);

    root = document.createElement("div");
    root.className = "pmp-root pmp-hidden";
    root.innerHTML = `
      <div class="pmp-header">
        <div class="pmp-header-left">
          <div class="pmp-avatar" data-avatar>${ICONS.music}</div>
          <div class="pmp-header-text">
            <div class="pmp-header-title" data-username>Профиль</div>
            <div class="pmp-header-sub">Музыка из профиля</div>
          </div>
        </div>
        <div class="pmp-header-actions">
          <button class="pmp-icon-btn" data-minimize title="Свернуть">${ICONS.minimize}</button>
          <button class="pmp-icon-btn" data-close title="Закрыть">${ICONS.close}</button>
        </div>
      </div>
      <div class="pmp-body">
        <div class="pmp-cover-wrap">
          <div class="pmp-cover" data-cover>${ICONS.music}</div>
          <div class="pmp-visualizer" data-visualizer>
            <span></span><span></span><span></span><span></span><span></span>
          </div>
        </div>
        <div class="pmp-track-title" data-title>—</div>
        <div class="pmp-track-artist" data-artist>Загрузка...</div>
      </div>
      <div class="pmp-progress-wrap">
        <span class="pmp-time" data-current>0:00</span>
        <div class="pmp-progress" data-progress>
          <div class="pmp-progress-fill" data-fill></div>
        </div>
        <span class="pmp-time" data-duration>0:00</span>
      </div>
      <div class="pmp-controls">
        <button class="pmp-btn pmp-btn-secondary" data-prev>${ICONS.prev}</button>
        <button class="pmp-btn pmp-btn-primary" data-play>
          <span class="pmp-icon-play">${ICONS.play}</span>
          <span class="pmp-icon-pause">${ICONS.pause}</span>
        </button>
        <button class="pmp-btn pmp-btn-secondary" data-next>${ICONS.next}</button>
      </div>
      <div class="pmp-playlist" data-playlist></div>
    `;
    document.body.appendChild(root);

    els = {
      avatar: $("[data-avatar]"),
      username: $("[data-username]"),
      cover: $("[data-cover]"),
      visualizer: $("[data-visualizer]"),
      title: $("[data-title]"),
      artist: $("[data-artist]"),
      current: $("[data-current]"),
      duration: $("[data-duration]"),
      progress: $("[data-progress]"),
      fill: $("[data-fill]"),
      play: $("[data-play]"),
      prev: $("[data-prev]"),
      next: $("[data-next]"),
      playlist: $("[data-playlist]"),
    };

    bindEvents();
    setupDrag();
    applyVisibility();
  }

  function bindEvents() {
    $("[data-close]").addEventListener("click", () => togglePlayer(false));
    $("[data-minimize]").addEventListener("click", () => {
      minimized = !minimized;
      root.classList.toggle("pmp-minimized", minimized);
    });

    els.play.addEventListener("click", togglePlay);
    els.prev.addEventListener("click", () => changeTrack(-1));
    els.next.addEventListener("click", () => changeTrack(1));

    els.progress.addEventListener("click", (e) => {
      if (!audio.duration) return;
      const rect = els.progress.getBoundingClientRect();
      const ratio = (e.clientX - rect.left) / rect.width;
      audio.currentTime = ratio * audio.duration;
    });

    audio.addEventListener("play", () => {
      els.play.classList.add("pmp-playing");
      els.cover.classList.add("pmp-spinning");
      els.visualizer.classList.add("pmp-active");
    });

    audio.addEventListener("pause", () => {
      els.play.classList.remove("pmp-playing");
      els.cover.classList.remove("pmp-spinning");
      els.visualizer.classList.remove("pmp-active");
    });

    audio.addEventListener("timeupdate", () => {
      if (!audio.duration || isDragging) return;
      const pct = (audio.currentTime / audio.duration) * 100;
      els.fill.style.width = `${pct}%`;
      els.current.textContent = formatTime(audio.currentTime);
    });

    audio.addEventListener("loadedmetadata", () => {
      els.duration.textContent = formatTime(audio.duration);
    });

    audio.addEventListener("ended", () => {
      if (currentIndex < tracks.length - 1) {
        loadTrack(currentIndex + 1, true);
      }
    });
  }

  function setupDrag() {
    const header = root.querySelector(".pmp-header");
    header.addEventListener("pointerdown", (e) => {
      if (e.target.closest(".pmp-icon-btn")) return;
      isDragging = true;
      const rect = root.getBoundingClientRect();
      dragOffset.x = e.clientX - rect.left;
      dragOffset.y = e.clientY - rect.top;
      header.setPointerCapture(e.pointerId);
    });

    header.addEventListener("pointermove", (e) => {
      if (!isDragging) return;
      root.style.left = `${e.clientX - dragOffset.x}px`;
      root.style.top = `${e.clientY - dragOffset.y}px`;
      root.style.right = "auto";
      root.style.bottom = "auto";
    });

    header.addEventListener("pointerup", () => {
      isDragging = false;
    });
  }

  function togglePlayer(show) {
    visible = show;
    api.storage.setForPlugin(PLUGIN_ID, "visible", visible);
    applyVisibility();
  }

  function applyVisibility() {
    if (!root) return;
    root.classList.toggle("pmp-hidden", !visible);
    fab.classList.toggle("pmp-fab-hidden", visible);
  }

  function setPlayingState(playing) {
    els.play.classList.toggle("pmp-playing", playing);
    els.cover.classList.toggle("pmp-spinning", playing);
    els.visualizer.classList.toggle("pmp-active", playing);
  }

  function updateUI() {
    const track = tracks[currentIndex];
    if (!track) {
      els.title.textContent = "Нет треков";
      els.artist.textContent = "Добавьте музыку в профиль";
      return;
    }

    els.title.textContent = track.title;
    els.artist.textContent = track.artist || "Без исполнителя";
    els.duration.textContent = formatTime(track.duration);
    els.prev.disabled = currentIndex === 0;
    els.next.disabled = currentIndex === tracks.length - 1;

    renderPlaylist();
  }

  function renderPlaylist() {
    els.playlist.innerHTML = tracks
      .map(
        (t, i) => `
      <div class="pmp-track-item${i === currentIndex ? " pmp-active" : ""}" data-idx="${i}">
        <span class="pmp-track-num">${i + 1}</span>
        <span class="pmp-track-name">${t.title}</span>
        <span class="pmp-track-dur">${formatTime(t.duration)}</span>
      </div>`
      )
      .join("");

    els.playlist.querySelectorAll(".pmp-track-item").forEach((item) => {
      item.addEventListener("click", () => {
        loadTrack(Number(item.dataset.idx), true);
      });
    });
  }

  async function loadTrack(index, autoplay = false) {
    if (!tracks.length) return;
    currentIndex = index;
    api.storage.setForPlugin(PLUGIN_ID, "trackIndex", currentIndex);

    const track = tracks[currentIndex];
    try {
      audio.src = await api.telegram.getFileUrl(track.document);
      updateUI();
      if (autoplay) await audio.play();
    } catch (err) {
      api.toast(`Ошибка загрузки: ${err.message || err}`);
    }
  }

  async function togglePlay() {
    if (!tracks.length) {
      api.toast("В профиле нет музыки");
      return;
    }
    if (audio.paused) {
      if (!audio.src) await loadTrack(currentIndex);
      try {
        await audio.play();
      } catch {
        api.toast("Не удалось воспроизвести");
      }
    } else {
      audio.pause();
    }
  }

  function changeTrack(delta) {
    const next = currentIndex + delta;
    if (next >= 0 && next < tracks.length) {
      loadTrack(next, true);
    }
  }

  async function loadProfileMusic() {
    try {
      const me = await api.telegram.getMe();
      const name = me.username ? `@${me.username}` : [me.first_name, me.last_name].filter(Boolean).join(" ");
      els.username.textContent = name;

      if (me.photo) {
        const photoUrl = await api.telegram.getFileUrl(me.photo);
        els.avatar.innerHTML = `<img src="${photoUrl}" alt="" />`;
      } else {
        els.avatar.textContent = (me.first_name?.[0] || "?").toUpperCase();
      }

      const result = await api.telegram.invoke("users.getSavedMusic", {
        id: { _: "inputUserSelf" },
        offset: 0,
        limit: 50,
        hash: 0,
      });

      const docs = result.documents || [];
      tracks = docs.map((doc) => {
        const meta = getAudioMeta(doc);
        return { ...meta, document: doc };
      });

      if (!tracks.length) {
        els.title.textContent = "Нет треков";
        els.artist.textContent = "Сохраните песню в профиль через плеер Telegram";
        api.toast("В профиле пока нет музыки");
        return;
      }

      if (currentIndex >= tracks.length) currentIndex = 0;
      updateUI();
      api.toast(`Загружено треков: ${tracks.length}`);
    } catch (err) {
      api.toast(`Ошибка: ${err.message || err}`);
      els.artist.textContent = "Не удалось загрузить музыку";
    }
  }

  api.command("music", async () => {
    togglePlayer(true);
    if (!tracks.length) await loadProfileMusic();
    return { text: "Плеер открыт" };
  });

  api.menu({
    label: "Музыка профиля",
    icon: "music",
    action: async () => {
      togglePlayer(true);
      if (!tracks.length) await loadProfileMusic();
    },
  });

  api.on("profile:music:changed", async () => {
    await loadProfileMusic();
    api.toast("Плейлист обновлён");
  });

  createPlayer();
  loadProfileMusic();
}

