.pmp-root {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 99999;
  width: 320px;
  background: var(--tg-bg, #17212b);
  color: var(--tg-text, #ffffff);
  border-radius: 16px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  overflow: hidden;
  user-select: none;
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.pmp-root.pmp-hidden {
  transform: translateY(120%);
  opacity: 0;
  pointer-events: none;
}

.pmp-root.pmp-minimized .pmp-body,
.pmp-root.pmp-minimized .pmp-progress-wrap,
.pmp-root.pmp-minimized .pmp-controls,
.pmp-root.pmp-minimized .pmp-playlist {
  display: none;
}

.pmp-root.pmp-minimized {
  width: auto;
  border-radius: 28px;
}

.pmp-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px 8px;
  cursor: grab;
}

.pmp-header:active {
  cursor: grabbing;
}

.pmp-header-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.pmp-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, #2aabee, #6c5ce7);
  display: grid;
  place-items: center;
  font-size: 14px;
  font-weight: 700;
  flex-shrink: 0;
  overflow: hidden;
}

.pmp-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.pmp-header-text {
  min-width: 0;
}

.pmp-header-title {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pmp-header-sub {
  font-size: 11px;
  color: var(--tg-hint, #8b9bab);
  margin-top: 1px;
}

.pmp-header-actions {
  display: flex;
  gap: 4px;
}

.pmp-icon-btn {
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--tg-hint, #8b9bab);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s, color 0.15s;
}

.pmp-icon-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--tg-text, #ffffff);
}

.pmp-icon-btn svg {
  width: 16px;
  height: 16px;
}

.pmp-body {
  padding: 0 16px 12px;
  text-align: center;
}

.pmp-cover-wrap {
  position: relative;
  display: inline-block;
  margin-bottom: 14px;
}

.pmp-cover {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: var(--tg-secondary, #232e3c);
  display: grid;
  place-items: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
  overflow: hidden;
}

.pmp-cover.pmp-spinning {
  animation: pmp-spin 8s linear infinite;
}

@keyframes pmp-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.pmp-cover svg {
  width: 48px;
  height: 48px;
  opacity: 0.4;
  color: var(--tg-hint, #8b9bab);
}

.pmp-visualizer {
  position: absolute;
  bottom: -6px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 3px;
  align-items: flex-end;
  height: 18px;
  opacity: 0;
  transition: opacity 0.3s;
}

.pmp-visualizer.pmp-active {
  opacity: 1;
}

.pmp-visualizer span {
  width: 3px;
  height: 6px;
  background: #2aabee;
  border-radius: 2px;
}

.pmp-visualizer.pmp-active span {
  animation: pmp-bar 0.7s ease-in-out infinite alternate;
}

.pmp-visualizer span:nth-child(1) { animation-delay: 0s; }
.pmp-visualizer span:nth-child(2) { animation-delay: 0.12s; }
.pmp-visualizer span:nth-child(3) { animation-delay: 0.24s; }
.pmp-visualizer span:nth-child(4) { animation-delay: 0.12s; }
.pmp-visualizer span:nth-child(5) { animation-delay: 0s; }

@keyframes pmp-bar {
  from { height: 4px; }
  to { height: 16px; }
}

.pmp-track-title {
  font-size: 15px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 4px;
}

.pmp-track-artist {
  font-size: 12px;
  color: var(--tg-hint, #8b9bab);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pmp-progress-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px 4px;
}

.pmp-time {
  font-size: 11px;
  color: var(--tg-hint, #8b9bab);
  min-width: 32px;
  font-variant-numeric: tabular-nums;
}

.pmp-progress {
  flex: 1;
  height: 4px;
  background: var(--tg-secondary, #232e3c);
  border-radius: 2px;
  cursor: pointer;
  position: relative;
}

.pmp-progress-fill {
  height: 100%;
  width: 0%;
  background: #2aabee;
  border-radius: 2px;
  transition: width 0.1s linear;
}

.pmp-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 8px 16px 12px;
}

.pmp-btn {
  border: none;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: transform 0.12s, opacity 0.12s;
}

.pmp-btn:active {
  transform: scale(0.9);
}

.pmp-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.pmp-btn-secondary {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--tg-secondary, #232e3c);
  color: var(--tg-text, #ffffff);
}

.pmp-btn-secondary svg {
  width: 20px;
  height: 20px;
}

.pmp-btn-primary {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: #2aabee;
  color: #ffffff;
  box-shadow: 0 4px 16px rgba(42, 171, 238, 0.4);
}

.pmp-btn-primary svg {
  width: 26px;
  height: 26px;
}

.pmp-btn-primary .pmp-icon-pause {
  display: none;
}

.pmp-btn-primary.pmp-playing .pmp-icon-play {
  display: none;
}

.pmp-btn-primary.pmp-playing .pmp-icon-pause {
  display: block;
}

.pmp-playlist {
  max-height: 160px;
  overflow-y: auto;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding: 6px 8px 10px;
}

.pmp-playlist::-webkit-scrollbar {
  width: 4px;
}

.pmp-playlist::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 2px;
}

.pmp-track-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.12s;
}

.pmp-track-item:hover {
  background: rgba(255, 255, 255, 0.06);
}

.pmp-track-item.pmp-active {
  background: rgba(42, 171, 238, 0.15);
}

.pmp-track-num {
  width: 20px;
  text-align: center;
  font-size: 12px;
  color: var(--tg-hint, #8b9bab);
}

.pmp-track-name {
  flex: 1;
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pmp-track-dur {
  font-size: 11px;
  color: var(--tg-hint, #8b9bab);
}

.pmp-fab {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 99998;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: none;
  background: #2aabee;
  color: #fff;
  cursor: pointer;
  box-shadow: 0 4px 20px rgba(42, 171, 238, 0.5);
  display: grid;
  place-items: center;
  transition: transform 0.2s, opacity 0.2s;
}

.pmp-fab:hover {
  transform: scale(1.06);
}

.pmp-fab.pmp-fab-hidden {
  opacity: 0;
  pointer-events: none;
  transform: scale(0.8);
}

.pmp-fab svg {
  width: 24px;
  height: 24px;
}
